# -*- coding: utf-8 -*-
# ---------- 1. El Corán ----------
add(1, "Corán 5:116–117", key="Q116", specs=["TQ3"],
 title="«¿Dijiste tú a la gente: “Tomadme a mí y a mi madre como dos dioses aparte de Dios”?»",
 ref="Corán, sura 5 (al-Maʾida), aleyas 116–117",
 ar_ref="سورة المائدة ١١٦–١١٧", site=WSQ, url=WS + "سورة_المائدة",
 es=["Y cuando Dios dijo: «Jesús, hijo de María, [[k:¿acaso dijiste tú a la gente: “Tomadme a mí y a mi madre como dos dioses aparte de Dios”?]]». Dijo: «¡Gloria a Ti! No me corresponde decir aquello a lo que no tengo derecho. Si lo hubiera dicho, Tú ya lo sabrías: Tú sabes lo que hay en mí y yo no sé lo que hay en Ti. Tú eres el que conoce lo oculto. [[a:No les dije sino lo que Tú me ordenaste: “Adorad a Dios, mi Señor y vuestro Señor”]]. Y fui testigo de ellos mientras estuve entre ellos; y cuando me llevaste, Tú eras quien los vigilaba. Tú eres testigo de todo»."],
 prueba="Es el versículo central del tema. Dios pregunta a Jesús si enseñó a tomarlo a él y a su madre como «dos dioses aparte de Dios». De aquí sale la idea de que el Corán entiende la fe cristiana como Dios + Jesús + María.",
 ojo="El versículo no dice «Trinidad» ni «tres»: habla de dos dioses «aparte de Dios» (min dun Allah). Ningún credo cristiano pone a María en la divinidad. En el credo de Nicea-Constantinopla (325/381) la tercera persona es el Espíritu Santo. Y en ningún lugar el Corán pone al Espíritu Santo entre los «tres».")

add(1, "Corán 5:72–75", key="Q73", specs=["TQ2"],
 title="«Dios es el tercero de tres»… «el Mesías no es más que un mensajero, y su madre… los dos comían alimentos»",
 ref="Corán, sura 5 (al-Maʾida), aleyas 72–75",
 ar_ref="سورة المائدة ٧٢–٧٥", site=WSQ, url=WS + "سورة_المائدة",
 es=["Han caído en la incredulidad los que dicen: «Dios es el Mesías, hijo de María». Y dijo el Mesías: «Hijos de Israel, [[a:adorad a Dios, mi Señor y vuestro Señor]]». A quien asocie algo a Dios, Dios le prohíbe el Paraíso y su morada será el Fuego; y los injustos no tendrán quien los auxilie. [[k:Han caído en la incredulidad los que dicen: «Dios es el tercero de tres»]]. No hay más dios que un Dios único, y si no dejan de decir lo que dicen, a los que de ellos no crean les alcanzará un castigo doloroso. ¿No se volverán a Dios pidiéndole perdón? Dios es perdonador, misericordioso. [[k:El Mesías, hijo de María, no es más que un mensajero]]; antes de él pasaron otros mensajeros. [[k:Y su madre es una mujer veraz; los dos comían alimentos]]. Mira cómo les explicamos las señales, y luego mira cómo se desvían."],
 prueba="El único versículo con la fórmula «tercero de tres» (thalith thalatha). Dos aleyas después, el argumento es que Jesús y su madre «comían alimentos», es decir, eran criaturas. Leído seguido, parece que los «tres» son Dios, Jesús y María.",
 ojo="El 5:73 no dice quiénes son los tres. «Comían alimentos» niega la divinidad de los dos, pero no prueba por sí solo que los «tres» incluyan a María. Además, la fórmula no describe la doctrina cristiana: los cristianos no dicen que Dios sea «uno de tres» dioses, sino un solo Dios en tres personas. Los comentaristas dan las dos lecturas (sección 2).")

add(1, "Corán 5:17", key="Q17", specs=["TQ1"],
 title="«¿Quién podría hacer algo frente a Dios si quisiera destruir al Mesías, hijo de María, y a su madre…?»",
 ref="Corán, sura 5 (al-Maʾida), aleya 17",
 ar_ref="سورة المائدة ١٧", site=WSQ, url=WS + "سورة_المائدة",
 es=["Han caído en la incredulidad los que dicen: «Dios es el Mesías, hijo de María». Di: «¿Quién podría hacer algo frente a Dios [[k:si quisiera destruir al Mesías, hijo de María, y a su madre]], y a todos los que están en la tierra?»"],
 prueba="Otra vez María aparece al lado de Jesús en un argumento contra su divinidad: Dios podría destruirlos a ambos.",
 ojo="Aquí María es solo un ejemplo de criatura mortal, junto a «todos los que están en la tierra». El versículo no dice que los cristianos la llamen diosa.")

add(1, "Corán 4:171", key="Q171", specs=["TQ4"],
 title="«No digáis “tres”»: el Mesías es «Su palabra, que depositó en María, y un espíritu de Él»",
 ref="Corán, sura 4 (al-Nisaʾ), aleya 171",
 ar_ref="سورة النساء ١٧١", site=WSQ, url=WS + "سورة_النساء",
 es=["¡Gente del Libro! No exageréis en vuestra religión y no digáis de Dios sino la verdad. El Mesías, Jesús hijo de María, es solo el mensajero de Dios [[k:y Su palabra, que Él depositó en María]], y un espíritu procedente de Él. Creed, pues, en Dios y en Sus mensajeros, [[k:y no digáis «tres»; dejadlo, que es mejor para vosotros]]. Dios es solo un Dios único; [[k:¡gloria a Él, lejos de tener un hijo!]] Suyo es cuanto hay en los cielos y en la tierra, y basta Dios como garante."],
 prueba="Es el otro versículo que habla de «tres». Aquí aparecen Dios, Jesús como «palabra» y un «espíritu de Él», y María solo como la que recibe la palabra.",
 ojo="Este versículo juega en contra de la lectura «Dios + Jesús + María»: el contexto nombra a Dios, a Su palabra y a un espíritu, que se parece más a Padre, Hijo y Espíritu. María no aparece como uno de los «tres». Por eso varios comentaristas explican aquí los «tres» como las tres personas (sección 2).")

add(1, "Corán 6:100–101 y 72:3", key="Q101", specs=["TQ5", "TQ6"],
 title="«¿Cómo iba a tener un hijo, si no ha tenido compañera?»: la filiación entendida como engendrar con una mujer",
 ref="Corán, sura 6 (al-Anʿam), aleyas 100–101; sura 72 (al-Jinn), aleya 3",
 ar_ref="سورة الأنعام ١٠٠–١٠١؛ سورة الجن ٣", site=WSQ, url=WS + "سورة_الأنعام · " + WS + "سورة_الجن",
 es=["Y han hecho a los genios socios de Dios, cuando Él los creó, y le han inventado [[a:hijos e hijas]] sin saber. ¡Gloria a Él, por encima de lo que le atribuyen! Creador de los cielos y la tierra: [[k:¿cómo iba a tener un hijo, si no ha tenido compañera?]] Él creó todas las cosas y Él conoce todas las cosas.",
     "Y que —ensalzada sea la majestad de nuestro Señor— [[k:no ha tomado compañera ni hijo]]."],
 prueba="El Corán argumenta contra la filiación con la idea de que un hijo requiere una «compañera» (sahiba). Es decir, entiende «hijo de Dios» como engendrado con una mujer. En el debate se usa para decir que el Corán imagina un Dios-Padre con esposa.",
 ojo="Ninguno de los dos versículos nombra a María ni a los cristianos. El 6:100 habla de quienes hacen a los genios socios de Dios y le atribuyen «hijos e hijas», que es la creencia de los árabes paganos. El 72:3 son palabras de unos genios. Que la «compañera» sea María es una deducción, no lo que dice el texto.")

add(1, "Corán 9:30–31", key="Q931", specs=["TQ7"],
 title="«Han tomado a sus rabinos y a sus monjes como señores aparte de Dios, y al Mesías»",
 ref="Corán, sura 9 (al-Tawba), aleyas 30–31",
 ar_ref="سورة التوبة ٣٠–٣١", site=WSQ, url=WS + "سورة_التوبة",
 es=["Y dicen los judíos: «ʿUzayr es hijo de Dios», y dicen los cristianos: «El Mesías es hijo de Dios». Eso es lo que dicen con sus bocas; imitan lo que decían los que no creyeron antes. ¡Que Dios los combata! ¡Cómo se desvían! [[k:Han tomado a sus rabinos y a sus monjes como señores aparte de Dios, y al Mesías, hijo de María]], y no se les ordenó más que adorar a un Dios único. No hay más dios que Él. ¡Gloria a Él, por encima de lo que le asocian!"],
 prueba="Aquí el Corán sí describe bien la creencia cristiana: «el Mesías es hijo de Dios». Y usa el mismo verbo que en 5:116 (ittakhadhu… min dun Allah, «tomaron… aparte de Dios») para los rabinos y monjes, a los que nadie llamaba dioses.",
 ojo="Esto sirve a los dos lados. Los apologistas musulmanes lo usan para decir que «tomar como dioses» en 5:116 significa venerar u obedecer, no declarar a María parte de la Trinidad. Pero entonces 5:116 deja de ser una descripción de la Trinidad, que es lo que se quería probar.")
